import{IN as o,OZ as s}from"./config.min.js";export const UNITS=Object.freeze(["us","metric"]);export function normalizeUnits(t){return t==="metric"?"metric":"us"}const e=(t,n)=>{const r=t.toFixed(n);return/^-0\.?0*$/.test(r)?r.slice(1):r};export function mass(t,n="us"){return normalizeUnits(n)==="metric"?`${e(t*1e3,1)} g`:`${e(t/s,2)} oz`}export function length(t,n="us"){return normalizeUnits(n)==="metric"?`${e(t*100,1)} cm`:`${e(t/o,2)} in`}export function sheetMass(t){return`${e(t/s,2)} oz (${e(t*1e3,1)} g)`}export function sheetLength(t){return`${Math.round(t/o*1e3)/1e3} in (${e(t*100,1)} cm)`}export function unitsLabel(t){return normalizeUnits(t)==="metric"?"Centimeters and grams":"Inches and ounces"}
